<?php require_once __DIR__ . '/../config/conexao.php'; require_once __DIR__ . '/../includes/funcoes.php'; $q=trim($_GET['q']??''); $categoria=trim($_GET['categoria']??''); $sql='SELECT p.*,c.nome AS categoria FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.ativo=1'; $params=[]; if($q!==''){ $sql.=' AND (p.nome LIKE :q OR p.descricao LIKE :q)'; $params['q']="%$q%"; } if($categoria!==''){ $sql.=' AND c.nome=:categoria'; $params['categoria']=$categoria; } $sql.=' ORDER BY p.nome'; $st=$pdo->prepare($sql);$st->execute($params);$produtos=$st->fetchAll(); ?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cardápio | Doppio Mocha</title><link rel="stylesheet" href="../css/code.css"></head><body><?php require __DIR__.'/../includes/cabecalho.php'; ?><main class="secao-produtos pagina-listagem"><div class="titulo-secao"><div><span class="subtitulo-secao">CARDÁPIO</span><h2><?= $q!==''?'Resultados da busca':'Nossos produtos' ?></h2></div><span><?= count($produtos) ?> produto(s)</span></div><?php if(!$produtos): ?><p class="mensagem-vazia">Não encontramos produtos com esse termo. Tente outra busca.</p><?php else: ?><section class="ferramentas-catalogo" aria-label="Filtros do catálogo">
<label for="busca-catalogo">Filtrar produtos por nome ou categoria</label>
<input type="search" id="busca-catalogo" placeholder="Ex.: cappuccino, cafés..." autocomplete="off">
<label for="ordenar-catalogo">Ordenar por</label>
<select id="ordenar-catalogo">
<option value="nome">Nome (A–Z)</option>
<option value="menor-preco">Menor preço</option>
<option value="maior-preco">Maior preço</option>
</select>
<p id="contador-resultados" class="resultado-filtro" aria-live="polite"></p>
</section>
<div class="grade-produtos"><?php foreach($produtos as $p): ?><article class="produto"><a class="produto-imagem" href="detalhes_produto.php?id=<?= (int)$p['id'] ?>"><div class="icone-produto"><img src="../imagens/<?= h($p['imagem']?:'cafe.png') ?>" alt="<?= h($p['nome']) ?>"></div></a><div class="produto-info"><p class="categoria-produto"><?= h($p['categoria']??'Especial') ?></p><h3><?= h($p['nome']) ?></h3><p class="descricao-produto"><?= h($p['descricao']) ?></p><p class="preco"><?= moeda((float)$p['preco']) ?></p><a class="link-detalhes" href="detalhes_produto.php?id=<?= (int)$p['id'] ?>">Ver detalhes</a><button type="button" class="botao-comprar" data-id="<?= (int)$p['id'] ?>" data-nome="<?= h($p['nome']) ?>" data-preco="<?= h((string)$p['preco']) ?>" data-imagem="../imagens/<?= h($p['imagem']?:'cafe.png') ?>">Adicionar ao carrinho</button></div></article><?php endforeach; ?></div><?php endif; ?></main><?php require __DIR__.'/../includes/rodape.php'; ?></body></html>
